package com.example.standup;
import android.app.*;import android.content.*;import android.os.*;
public class ReminderService extends Service {
 Handler handler=new Handler();final long INTERVAL=20*60*1000L;Runnable tick;NotificationManager manager;
 public void onCreate(){super.onCreate();manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("running","Timer status",NotificationManager.IMPORTANCE_LOW));manager.createNotificationChannel(new NotificationChannel("breaks","Stand-up reminders",NotificationManager.IMPORTANCE_HIGH));}
 public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&"STOP".equals(intent.getAction())){getSharedPreferences("timer",0).edit().putBoolean("active",false).remove("end").apply();if(tick!=null)handler.removeCallbacks(tick);stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();return START_NOT_STICKY;}
 long end=getSharedPreferences("timer",0).getLong("end",0);if(end<=0)end=System.currentTimeMillis()+INTERVAL;getSharedPreferences("timer",0).edit().putBoolean("active",true).putLong("end",end).apply();startForeground(1,status());schedule();return START_STICKY;}
 Notification status(){Intent open=new Intent(this,MainActivity.class);PendingIntent p=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"running").setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("StandUp Reminder is running").setContentText("A movement break every 20 minutes").setContentIntent(p).setOngoing(true).build();}
 void schedule(){if(tick!=null)handler.removeCallbacks(tick);tick=()->{if(!getSharedPreferences("timer",0).getBoolean("active",false))return;long now=System.currentTimeMillis(),end=getSharedPreferences("timer",0).getLong("end",now+INTERVAL);if(now>=end){manager.notify(2,new Notification.Builder(this,"breaks").setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("Time to stand up!").setContentText("Take a short walk, stretch, and rest your eyes.").setAutoCancel(true).build());long next=now+INTERVAL;getSharedPreferences("timer",0).edit().putLong("end",next).apply();end=next;}handler.postDelayed(tick,Math.min(1000,Math.max(100,end-now)));};handler.post(tick);}
 public void onDestroy(){if(tick!=null)handler.removeCallbacks(tick);super.onDestroy();}public IBinder onBind(Intent i){return null;}
}
